// Package slicekit holds small slice helpers.
package slicekit

// Number is any numeric type.
type Number interface {
	~int | ~int64 | ~float64
}

// Ordered is any type that supports < and >.
type Ordered interface {
	Number | ~string
}

// Max returns the largest value and false for an empty slice.
func Max[T Ordered](xs []T) (T, bool) {
	var best T
	if len(xs) == 0 {
		return best, false
	}
	best = xs[0]
	for _, x := range xs[1:] {
		if x > best {
			best = x
		}
	}
	return best, true
}

// Reverse returns a reversed copy.
func Reverse[T any](xs []T) []T {
	out := make([]T, len(xs))
	for i, x := range xs {
		out[len(xs)-1-i] = x
	}
	return out
}

func MaxInts(xs []int) (int, bool) { return Max(xs) }
func MaxFloats(xs []float64) (float64, bool) { return Max(xs) }
func ReverseInts(xs []int) []int { return Reverse(xs) }
func ReverseFloats(xs []float64) []float64 { return Reverse(xs) }
func ReverseStrings(xs []string) []string { return Reverse(xs) }

