// Package slicekit holds small slice helpers.
package slicekit

// Number is any numeric type.
type Number interface {
	~int | ~int64 | ~float64
}

// Ordered is any type that supports < and >.
type Ordered interface {
	Number | ~string
}

// Sum adds up the values.
func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

// Max returns the largest value and false for an empty slice.
func Max[T Ordered](xs []T) (T, bool) {
	var best T
	if len(xs) == 0 {
		return best, false
	}
	best = xs[0]
	for _, x := range xs[1:] {
		if x > best {
			best = x
		}
	}
	return best, true
}

// IndexOf returns the position of the first v in xs, or -1.
func IndexOf[T comparable](xs []T, v T) int {
	for i, x := range xs {
		if x == v {
			return i
		}
	}
	return -1
}

// Reverse returns a reversed copy.
func Reverse[T any](xs []T) []T {
	out := make([]T, len(xs))
	for i, x := range xs {
		out[len(xs)-1-i] = x
	}
	return out
}

// Filter keeps the values for which keep returns true.
func Filter[T any](xs []T, keep func(T) bool) []T {
	var out []T
	for _, x := range xs {
		if keep(x) {
			out = append(out, x)
		}
	}
	return out
}

func SumInts(xs []int) int { return Sum(xs) }
func SumFloats(xs []float64) float64 { return Sum(xs) }
func MaxInts(xs []int) (int, bool) { return Max(xs) }
func MaxFloats(xs []float64) (float64, bool) { return Max(xs) }
func MaxStrings(xs []string) (string, bool) { return Max(xs) }
func IndexOfInts(xs []int, v int) int { return IndexOf(xs, v) }
func IndexOfStrings(xs []string, v string) int { return IndexOf(xs, v) }
func ReverseInts(xs []int) []int { return Reverse(xs) }
func ReverseFloats(xs []float64) []float64 { return Reverse(xs) }
func ReverseStrings(xs []string) []string { return Reverse(xs) }
func FilterInts(xs []int, keep func(int) bool) []int { return Filter(xs, keep) }
func FilterStrings(xs []string, keep func(string) bool) []string { return Filter(xs, keep) }

