// Package batchlib holds small slice helpers.
package batchlib

// Contains reports whether v occurs in xs.
func Contains[T comparable](xs []T, v T) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

// IndexOf returns the position of the first v in xs, or -1.
func IndexOf[T comparable](xs []T, v T) int {
	for i, x := range xs {
		if x == v {
			return i
		}
	}
	return -1
}

// Filter keeps the values for which keep returns true.
func Filter[T any](xs []T, keep func(T) bool) []T {
	var out []T
	for _, x := range xs {
		if keep(x) {
			out = append(out, x)
		}
	}
	return out
}

func ContainsInts(xs []int, v int) bool { return Contains(xs, v) }
func ContainsStrings(xs []string, v string) bool { return Contains(xs, v) }
func IndexOfInts(xs []int, v int) int { return IndexOf(xs, v) }
func IndexOfStrings(xs []string, v string) int { return IndexOf(xs, v) }
func FilterInts(xs []int, keep func(int) bool) []int { return Filter(xs, keep) }
func FilterStrings(xs []string, keep func(string) bool) []string { return Filter(xs, keep) }

