// Package slicekit holds small slice helpers.
package slicekit

// Number is any numeric type.
type Number interface {
	~int | ~int64 | ~float64
}

// Ordered is any type that supports < and >.
type Ordered interface {
	Number | ~string
}

// Sum adds up the values.
func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

// Max returns the largest value and false for an empty slice.
func Max[T Ordered](xs []T) (T, bool) {
	var best T
	if len(xs) == 0 {
		return best, false
	}
	best = xs[0]
	for _, x := range xs[1:] {
		if x > best {
			best = x
		}
	}
	return best, true
}

// Contains reports whether v occurs in xs.
func Contains[T comparable](xs []T, v T) bool {
	for _, x := range xs {
		if x == v {
			return true
		}
	}
	return false
}

// Unique keeps the first occurrence of every value.
func Unique[T comparable](xs []T) []T {
	seen := map[T]bool{}
	var out []T
	for _, x := range xs {
		if !seen[x] {
			seen[x] = true
			out = append(out, x)
		}
	}
	return out
}

func SumInts(xs []int) int { return Sum(xs) }
func SumFloats(xs []float64) float64 { return Sum(xs) }
func MaxInts(xs []int) (int, bool) { return Max(xs) }
func MaxFloats(xs []float64) (float64, bool) { return Max(xs) }
func ContainsInts(xs []int, v int) bool { return Contains(xs, v) }
func ContainsStrings(xs []string, v string) bool { return Contains(xs, v) }
func UniqueInts(xs []int) []int { return Unique(xs) }
func UniqueStrings(xs []string) []string { return Unique(xs) }

