	exEq(t, "SumInts", slicekit.SumInts([]int{3, 1, 4, 1, 5}), int(14))
	exEq(t, "SumInts", slicekit.SumInts([]int{}), int(0))
	exEq(t, "SumInts", slicekit.SumInts([]int{7}), int(7))
