package rowtools_test

import (
	"reflect"
	"testing"

	"example.com/rowtoolsmod/rowtools"
)

func exEq(t *testing.T, name string, got, want any) {
	t.Helper()
	if !reflect.DeepEqual(got, want) && !(reflect.ValueOf(got).Kind() == reflect.Slice && reflect.ValueOf(want).Kind() == reflect.Slice && reflect.ValueOf(got).Len() == 0 && reflect.ValueOf(want).Len() == 0) {
		t.Errorf("%s: got %v, want %v", name, got, want)
	}
}

func TestExamples(t *testing.T) {
	exEq(t, "SumInts", rowtools.SumInts([]int{3, 1, 4, 1, 5}), int(14))
	exEq(t, "SumInts", rowtools.SumInts([]int{}), int(0))
	exEq(t, "SumInts", rowtools.SumInts([]int{7}), int(7))
	exEq(t, "SumInts", rowtools.SumInts([]int{2, 2, 9, 2}), int(15))
	{
		got, ok := rowtools.MaxInts([]int{3, 1, 4, 1, 5})
		exEq(t, "MaxInts", []any{got, ok}, []any{int(5), true})
	}
	{
		got, ok := rowtools.MaxInts([]int{})
		exEq(t, "MaxInts", []any{got, ok}, []any{int(0), false})
	}
	{
		got, ok := rowtools.MaxInts([]int{7})
		exEq(t, "MaxInts", []any{got, ok}, []any{int(7), true})
	}
	{
		got, ok := rowtools.MaxInts([]int{2, 2, 9, 2})
		exEq(t, "MaxInts", []any{got, ok}, []any{int(9), true})
	}
}

