// Package listutil holds small slice helpers.
package listutil

// Number is any numeric type.
type Number interface {
	~int | ~int64 | ~float64
}

// Sum adds up the values.
func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

// IndexOf returns the position of the first v in xs, or -1.
func IndexOf[T comparable](xs []T, v T) int {
	for i, x := range xs {
		if x == v {
			return i
		}
	}
	return -1
}

// Reverse returns a reversed copy.
func Reverse[T any](xs []T) []T {
	out := make([]T, len(xs))
	for i, x := range xs {
		out[len(xs)-1-i] = x
	}
	return out
}

func SumInts(xs []int) int { return Sum(xs) }
func SumFloats(xs []float64) float64 { return Sum(xs) }
func IndexOfInts(xs []int, v int) int { return IndexOf(xs, v) }
func IndexOfStrings(xs []string, v string) int { return IndexOf(xs, v) }
func ReverseInts(xs []int) []int { return Reverse(xs) }
func ReverseFloats(xs []float64) []float64 { return Reverse(xs) }
func ReverseStrings(xs []string) []string { return Reverse(xs) }

