package listutil_test

import (
	"reflect"
	"testing"

	"example.com/listutilmod/listutil"
)

func exEq(t *testing.T, name string, got, want any) {
	t.Helper()
	if !reflect.DeepEqual(got, want) && !(reflect.ValueOf(got).Kind() == reflect.Slice && reflect.ValueOf(want).Kind() == reflect.Slice && reflect.ValueOf(got).Len() == 0 && reflect.ValueOf(want).Len() == 0) {
		t.Errorf("%s: got %v, want %v", name, got, want)
	}
}

func TestExamples(t *testing.T) {
	exEq(t, "SumInts", listutil.SumInts([]int{3, 1, 4, 1, 5}), int(14))
	exEq(t, "SumInts", listutil.SumInts([]int{}), int(0))
	exEq(t, "SumInts", listutil.SumInts([]int{7}), int(7))
	exEq(t, "SumInts", listutil.SumInts([]int{2, 2, 9, 2}), int(15))
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{3, 1, 4, 1, 5}, 1), 1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{3, 1, 4, 1, 5}, 9), -1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{}, 1), -1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{}, 9), -1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{7}, 1), -1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{7}, 9), -1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{2, 2, 9, 2}, 1), -1)
	exEq(t, "IndexOfInts", listutil.IndexOfInts([]int{2, 2, 9, 2}, 9), 2)
}

